{
  "name": "memory-enhancement",
  "version": "0.5.0",
  "description": "A dream skill that runs a natural-language-triggered, four-phase memory-consolidation cycle over this project's auto-memory files (~/.claude/projects/<project>/memory/): orient, gather signal from recent session transcripts, consolidate (merge duplicates, drop stale entries, resolve contradictions, author a new memory file for any signal with no existing memory home, back up each existing changed detail file alongside itself before writing -- new files and the index, re-derived separately, are excluded), and update the MEMORY.md index (kept under its 200-line/25KB load cutoff) -- optionally compressing touched detail files caveman-style via cc-knowledge's cc-compress skill when that plugin is enabled (silent no-op otherwise, no hard dependency). A turn-end hook (an in-process mods module) flags a genuinely new next session (not a same-session /clear, /compact, or --resume) as dream-due; a session-start hook consumes that flag and nudges Claude to run one, on by default (see userConfig auto_dream). A self-improvement skill reflects on a session's own tool calls and reasoning to find concrete efficiency lessons, reports them to the user, and saves durable, deduped findings as feedback memory.",
  "author": {
    "name": "Kwitsch"
  },
  "userConfig": {
    "auto_dream": {
      "type": "boolean",
      "title": "Auto-dream nudge",
      "description": "Values: true (or unset) = the session-start hook nudges Claude to run a memory dream cycle when a previous session's turn-end hook flagged one as due; false = the flag is still written but never consumed/nudged. Fail-open: only the literal value false disables -- the hook itself only suggests a dream cycle via a context message, it does not write any file itself, so an unconfigured value is treated as enabled, matching the default below. Default: true.",
      "default": true
    }
  }
}
